-- CREACIÓN DE TABLAS DE hotel-database (ESTRUCTURA)CREATE TABLE clientes (    id_cliente INT GENERATED ALWAYS AS IDENTITY,    dni_cliente VARCHAR(45),    nombre_cliente VARCHAR(45),    apellido_cliente VARCHAR(45),    telefono_cliente VARCHAR(45),    email_cliente VARCHAR(100),    CONSTRAINT pk_id_cliente PRIMARY KEY (id_cliente));CREATE TABLE habitaciones (    id_habitacion INT GENERATED ALWAYS AS IDENTITY,    numero_habitacion INTEGER,    tipo_habitacion VARCHAR(45),    precionoche_habitacion DECIMAL(10,2),    estado_habitacion VARCHAR(45),    CONSTRAINT pk_id_habitacion PRIMARY KEY (id_habitacion));CREATE TABLE empleados (    id_empleado INT GENERATED ALWAYS AS IDENTITY,    dni_empleado VARCHAR(45),    nombre_empleado VARCHAR(45),    apellido_empleado VARCHAR(45),    puesto_empleado VARCHAR(45),    sueldo_empleado DECIMAL(10,2),    CONSTRAINT pk_id_empleado PRIMARY KEY (id_empleado));CREATE TABLE reservas (    id_reserva INT GENERATED ALWAYS AS IDENTITY,    id_habitacion_reserva INTEGER,    id_cliente_reserva INTEGER,    id_empleado_reserva INTEGER,    fechaentrada_reserva DATE,    fechasalida_reserva DATE,    estado_reserva VARCHAR(45),    CONSTRAINT pk_id_reserva PRIMARY KEY (id_reserva),    CONSTRAINT fk_id_habitacion_reserva FOREIGN KEY (id_habitacion_reserva) REFERENCES habitaciones(id_habitacion),    CONSTRAINT fk_id_cliente_reserva FOREIGN KEY (id_cliente_reserva) REFERENCES clientes(id_cliente),    CONSTRAINT fk_empleado_reserva FOREIGN KEY (id_empleado_reserva) REFERENCES empleados(id_empleado));CREATE TABLE pagos (    id_pago INT GENERATED ALWAYS AS IDENTITY,    id_reserva_pago INTEGER,    monto_pago DECIMAL(10,2),    fecha_pago DATE,    metodopago_pago VARCHAR(45),    CONSTRAINT pk_id_pago PRIMARY KEY (id_pago),    CONSTRAINT fk_id_reserva_pago FOREIGN KEY (id_reserva_pago) REFERENCES reservas(id_reserva));CREATE TABLE servicios (    id_servicio INT GENERATED ALWAYS AS IDENTITY,    nombre_servicio VARCHAR(45),    descripcion_servicio VARCHAR(255),    precio_servicio DECIMAL(10,2),    CONSTRAINT pk_id_servicio PRIMARY KEY (id_servicio));CREATE TABLE servicioxreserva (    id_sxr INT GENERATED ALWAYS AS IDENTITY,    id_servicio_sxr INTEGER,    id_reserva_sxr INTEGER,    fechaservicio_sxr DATE,    cantidad_sxr INTEGER,    CONSTRAINT pk_id_sxr PRIMARY KEY (id_sxr),    CONSTRAINT fk_id_servicio_sxr FOREIGN KEY (id_servicio_sxr) REFERENCES servicios(id_servicio),    CONSTRAINT fk_id_reserva_sxr FOREIGN KEY (id_reserva_sxr) REFERENCES reservas(id_reserva));